-- Leaderboard test and demo data for story #10 (the leaderboard backend, card #121): 62 new accounts, all @example.com.
-- Requires database/migrations/001_auth.sql to 013_leaderboard.sql. Safe to rerun: these accounts are reset to the values
-- below (names, passwords, personal details, join state and ALL their workouts) and every other account is left alone.
-- It never touches Marcus, Dana, Riley, Taylor, Sean, Priya, Jordan or the personal-details accounts, so stories 7, 8, 9 and
-- 18 keep their numbers. The expected scores and the step-by-step checks are in task-tests/10-leaderboard-backend.html.
--
-- Load it from the repo root (any time after the migrations):
--   mysql --default-character-set=utf8mb4 -u root cse442_2026_fall_team_y_db < database/seeds/leaderboard.sql
--
-- Who is who (full table in the task test): Ana, Ben, Cy, Dee, Eli, Gus, Hana, Ivy, Zed, Nova, Sky, Pia and Rex are the
-- backend test cast; Casey, Luis, Robin, Noor and Max are the people story #10's acceptance tests log in as (Max has
-- users.is_test = 1, the only account that does); the other 44 are demo members who fill out the boards. Everyone has
-- finished onboarding. Passwords are in database/seeds/README.md. Weights are lb; each best below comes from one set in a
-- finished workout, and the other finished workouts hold a lighter set so they only add to the workout count.
-- Times are fixed UTC dates in September and October 2026. "Pending test workout" sessions are unfinished (completed_at
-- NULL) on purpose: some tests finish them and put them back.

CREATE TEMPORARY TABLE lb_people (
    full_name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, password_hash VARCHAR(255) NOT NULL,
    gender VARCHAR(20) NULL, bodyweight_lb DECIMAL(4, 1) NULL, scoring_table VARCHAR(5) NULL,
    joined TINYINT NOT NULL, is_test TINYINT NOT NULL
) DEFAULT CHARSET = utf8mb4;

CREATE TEMPORARY TABLE lb_sessions (
    email VARCHAR(254) NOT NULL, started_at DATETIME NOT NULL, completed_at DATETIME NULL,
    day_name VARCHAR(100) NOT NULL, exercises TEXT NOT NULL
) DEFAULT CHARSET = utf8mb4;

CREATE TEMPORARY TABLE lb_sets (
    email VARCHAR(254) NOT NULL, started_at DATETIME NOT NULL, exercise VARCHAR(100) NOT NULL,
    set_number SMALLINT NOT NULL, weight_lb DECIMAL(6, 2) NOT NULL, reps SMALLINT NOT NULL
) DEFAULT CHARSET = utf8mb4;

-- Accounts.
    SELECT full_name, email, password_hash FROM lb_people ORDER BY email
ON DUPLICATE KEY UPDATE full_name = VALUES(full_name), password_hash = VALUES(password_hash);
UPDATE users u JOIN lb_people l ON l.email = u.email SET u.is_test = l.is_test;

-- Onboarding finished (goal Strength, Beginner, Full gym access), so logging in opens the Dashboard.
    SELECT u.id, 'strength' FROM users u JOIN lb_people l ON l.email = u.email
ON DUPLICATE KEY UPDATE training_goal = VALUES(training_goal);
    SELECT u.id, 'beginner' FROM users u JOIN lb_people l ON l.email = u.email
ON DUPLICATE KEY UPDATE experience = VALUES(experience);
DELETE FROM user_equipment WHERE user_id IN (SELECT u.id FROM users u JOIN lb_people l ON l.email = u.email);
    SELECT u.id, 'full_gym' FROM users u JOIN lb_people l ON l.email = u.email;

-- Personal details and the leaderboard join. Hana has a row with no body weight or gender.
DELETE FROM user_profile WHERE user_id IN (SELECT u.id FROM users u JOIN lb_people l ON l.email = u.email);
    SELECT u.id, l.bodyweight_lb, l.gender, IF(l.joined = 1, UTC_TIMESTAMP(), NULL), l.scoring_table
    FROM users u JOIN lb_people l ON l.email = u.email;

-- Workouts: all of these accounts' workouts are replaced.
DELETE FROM workout_sessions WHERE user_id IN (SELECT u.id FROM users u JOIN lb_people l ON l.email = u.email);
    SELECT u.id, NULL, 'Leaderboard seed', s.day_name, '', CAST(s.exercises AS JSON), s.started_at, s.completed_at
    FROM lb_sessions s JOIN users u ON u.email = s.email;
    SELECT ws.id, v.exercise, v.set_number, v.weight_lb, v.reps, ws.started_at + INTERVAL 5 MINUTE, ws.started_at + INTERVAL 5 MINUTE
    FROM workout_sessions ws
    JOIN users u ON u.id = ws.user_id
    JOIN lb_sets v ON v.email = u.email AND v.started_at = ws.started_at
    WHERE ws.plan_name = 'Leaderboard seed';

DROP TEMPORARY TABLE lb_sets;
DROP TEMPORARY TABLE lb_sessions;
DROP TEMPORARY TABLE lb_people;
